          <th scope="col">Band</th>
          <th scope="col">Scaled</th>
          <th scope="col">Thrum</th>
          <th scope="col">Spool</th>
          <th scope="col">Drag</th>
          <th scope="col">Norm</th>
          <th scope="col">Outlier</th>
